const d = $input.first().json;

function row(label, value) {
  return `<div class="field"><span class="label">${label}</span><span class="line">${value !== undefined && value !== '' ? value : ''}</span></div>`;
}

function copyBlock(copyLabel) {
  return `
  <div class="receipt">
    <div class="header">
      <div class="logo">@</div>
      <div class="school-title">
        <div class="school-name">The Smart School <span class="proj">A project of The City School</span></div>
        <div class="campus">Bara Kahu Campus Islamabad</div>
        <div class="phone">051-2322122</div>
        <div class="receipt-tag">ADMISSION RECEIPT</div>
      </div>
      <div class="copy-label">${copyLabel}<br><span class="dated">Dated: <b>${d.date}</b></span><br><span class="receiptno">Receipt#: <b>${d.receiptNo}</b></span></div>
    </div>

    <div class="row two">
      ${row('Student Name:', d.studentName)}
      ${row('Father Name:', d.fatherName)}
    </div>
    <div class="row two">
      ${row('Class:', d.className)}
      ${row('Rs.', '( ' + d.totalFeeWords + ' )')}
    </div>
    <div class="row three">
      ${row('(I) Monthly Fee', d.monthlyFee)}
      ${row('(ii) Admission Fee', d.admissionFee)}
    </div>
    <div class="row two">
      ${row('(iii) Security', d.security)}
      ${row('(iv) Annual Fee', d.annualFee)}
      ${row('(v) Other Dues', d.otherDues)}
    </div>
    <div class="row one">
      ${row('Parents Contact #:', d.parentsContact)}
    </div>
    <div class="row two">
      ${row('Amount Paid:', d.amountPaid)}
      ${row('Balance:', d.balance)}
    </div>

    <div class="sign-row">
      <div class="sign">Admin &amp; Account Officer Signature</div>
      <div class="sign">Parents Signature</div>
    </div>
  </div>`;
}

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  @page { size: A4; margin: 10mm; }
  body { font-family: Georgia, 'Times New Roman', serif; color:#111; margin:0; }
  .receipt { padding: 14px 18px; }
  .header { display:flex; align-items:flex-start; justify-content:space-between; border-bottom: 1px solid #333; padding-bottom:6px; margin-bottom:14px;}
  .logo { font-size: 26px; font-weight:bold; border:2px solid #333; border-radius:6px; width:42px; height:42px; text-align:center; line-height:38px; margin-right:10px;}
  .school-title { flex:1; text-align:center; }
  .school-name { font-family: 'Brush Script MT', cursive; font-size: 30px; font-weight:bold; }
  .proj { font-family: Georgia, serif; font-size: 13px; font-weight:normal; margin-left:8px;}
  .campus { text-decoration: underline; font-size: 16px; margin-top:2px;}
  .phone { font-size: 12px; }
  .receipt-tag { display:inline-block; background:#555; color:#fff; padding:2px 14px; margin-top:4px; letter-spacing:1px; font-size:14px;}
  .copy-label { font-weight:bold; font-size:15px; text-align:right; min-width:150px;}
  .dated, .receiptno { font-weight:normal; font-size:12px; }
  .row { display:flex; gap:14px; margin-bottom:10px; }
  .row.one .field { flex: 1 1 100%; }
  .row.two .field { flex: 1 1 48%; }
  .row.three .field { flex: 1 1 48%; }
  .field { display:flex; align-items:flex-end; gap:6px; font-size:14px; }
  .label { white-space:nowrap; }
  .line { flex:1; border-bottom: 1px solid #333; min-height: 16px; padding-left:4px; }
  .sign-row { display:flex; justify-content:space-between; margin-top:40px; font-size:13px; }
  .sign { border-top: 1px solid #333; padding-top:4px; width:40%; text-align:center; }
  .cut-line { border-top: 1px dashed #333; margin: 6px 0 6px 0; }
</style>
</head>
<body>
  ${copyBlock('Parent Copy')}
  <div class="cut-line"></div>
  ${copyBlock('School Copy')}
</body>
</html>`;

return [{ json: { ...d, html } }];

// ================= Build Receipt Data =================
const body = $input.first().json.body || $input.first().json;

function numberToWords(num) {
  num = Math.round(Number(num) || 0);
  if (num === 0) return 'Zero';
  const a = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten',
    'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
  function two(n) {
    if (n < 20) return a[n];
    return b[Math.floor(n / 10)] + (n % 10 ? ' ' + a[n % 10] : '');
  }
  function three(n) {
    if (n > 99) return a[Math.floor(n / 100)] + ' Hundred' + (n % 100 ? ' ' + two(n % 100) : '');
    return two(n);
  }
  let result = '';
  const crore = Math.floor(num / 10000000); num %= 10000000;
  const lakh = Math.floor(num / 100000); num %= 100000;
  const thousand = Math.floor(num / 1000); num %= 1000;
  const rest = num;
  if (crore) result += three(crore) + ' Crore ';
  if (lakh) result += three(lakh) + ' Lakh ';
  if (thousand) result += three(thousand) + ' Thousand ';
  if (rest) result += three(rest);
  return result.trim() + ' Only';
}

const totalFee = Number(body.totalFee || 0);
const monthlyFee = Number(body.monthlyFee || 0);
const admissionFee = Number(body.admissionFee || 0);
const security = Number(body.security || 0);
const annualFee = Number(body.annualFee || 0);
const otherDues = Number(body.otherDues || 0);
const amountPaid = Number(body.amountPaid || 0);
const balance = totalFee - amountPaid;

const now = new Date();
const dateStr = now.toLocaleDateString('en-GB').split('/').join('-'); // DD-MM-YYYY
const receiptNo = 'SS-' + now.getFullYear().toString().slice(-2) +
  String(now.getMonth() + 1).padStart(2, '0') +
  String(now.getDate()).padStart(2, '0') + '-' +
  String(now.getHours()).padStart(2, '0') +
  String(now.getMinutes()).padStart(2, '0') +
  String(now.getSeconds()).padStart(2, '0');

return [{
  json: {
    receiptNo,
    date: dateStr,
    studentName: body.studentName || '',
    fatherName: body.fatherName || '',
    className: body.className || '',
    totalFee,
    totalFeeWords: numberToWords(totalFee),
    monthlyFee,
    admissionFee,
    security,
    annualFee,
    otherDues,
    parentsContact: body.parentsContact || '',
    amountPaid,
    balance,
    timestamp: now.toISOString()
  }
}];
